define('KARVIA_APP', true);$peran_halaman='siswa';$halaman_aktif='konsultasi';$judul_halaman='Ruang Konsultasi BK';require_once __DIR__.'/../includes/header.php';
$pdo=db();$siswa_id=(int)auth_pengguna()['id'];$stmt=$pdo->prepare('SELECT mapel_favorit,kekuatan,catatan_minat FROM refleksi_diri WHERE siswa_id=:id');$stmt->execute(['id'=>$siswa_id]);$refleksi=$stmt->fetch()?:[];$stmt=$pdo->prepare('SELECT nama FROM profesi_disimpan d JOIN profesi p ON p.id=d.profesi_id WHERE d.siswa_id=:id ORDER BY p.nama');$stmt->execute(['id'=>$siswa_id]);$profesi=$stmt->fetchAll();$stmt=$pdo->prepare('SELECT opsi_a,catatan_a,opsi_b,catatan_b,kriteria FROM pilihan_banding WHERE siswa_id=:id');$stmt->execute(['id'=>$siswa_id]);$banding=$stmt->fetch()?:[];$stmt=$pdo->prepare('SELECT tujuan,langkah_1,langkah_2 FROM rencana_karier WHERE siswa_id=:id');$stmt->execute(['id'=>$siswa_id]);$rencana=$stmt->fetch()?:[];$stmt=$pdo->prepare('SELECT hal_baru,hambatan,dukungan,dibuat_pada FROM jurnal_refleksi WHERE siswa_id=:id ORDER BY dibuat_pada DESC,id DESC');$stmt->execute(['id'=>$siswa_id]);$jurnal=$stmt->fetchAll();$stmt=$pdo->prepare('SELECT id,sekolah_id,pesan_siswa,status,dibagikan_pada FROM berbagi_catatan WHERE siswa_id=:id');$stmt->execute(['id'=>$siswa_id]);$berbagi=$stmt->fetch()?:null;$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_wajib();$pesan=trim((string)($_POST['pesan_siswa']??''));if(mb_strlen($pesan)>2000)$errors[]='Pesan maksimal 2.000 karakter.';if(!$errors){$sekolah=(int)auth_sekolah_id();$stmt=$pdo->prepare("INSERT INTO berbagi_catatan (siswa_id,sekolah_id,pesan_siswa,status,dibagikan_pada,dibaca_pada,diperbarui_pada) VALUES (:siswa_id,:sekolah_id,:pesan,'baru',NOW(),NULL,NULL) ON DUPLICATE KEY UPDATE sekolah_id=VALUES(sekolah_id),pesan_siswa=VALUES(pesan_siswa),status='baru',dibagikan_pada=NOW(),dibaca_pada=NULL,diperbarui_pada=NOW()");$stmt->execute(['siswa_id'=>$siswa_id,'sekolah_id'=>$sekolah,'pesan'=>$pesan?:null]);log_aktivitas('bagikan_catatan','Siswa membagikan ringkasan karier ke Guru BK.');flash_set('sukses','Ringkasan berhasil dibagikan kepada Guru BK di sekolahmu.');redirect('siswa/konsultasi.php');}}
function siswa_nilai($value): string { if($value===null||$value==='')return 'Belum diisi';if(is_array($value))return $value?implode(', ',array_map('strval',$value)):'Belum diisi';return (string)$value; }
function siswa_json($value): string {if(!$value)return 'Belum diisi';$decoded=json_decode((string)$value,true);return is_array($decoded)?siswa_nilai($decoded):'Belum diisi';}
