<section class="rounded-2xl border bg-white p-5"><h2 class="font-bold">Bandingkan Pilihan</h2><?php if(!$banding):?><p class="mt-2 text-sm text-slate-500">Belum diisi.</p><?php else:?><p class="mt-2 text-sm"><strong>A:</strong> <?=e($banding['opsi_a'])?> — <?=e(siswa_nilai($banding['catatan_a']))?></p><p class="text-sm"><strong>B:</strong> <?=e($banding['opsi_b'])?> — <?=e(siswa_nilai($banding['catatan_b']))?></p><p class="text-sm"><strong>Kriteria:</strong> <?=e(siswa_json($banding['kriteria']))?></p><?php endif;?></section>
<section class="rounded-2xl border bg-white p-5"><h2 class="font-bold">Rencana Langkahku</h2><?php if(!$rencana):?><p class="mt-2 text-sm text-slate-500">Belum diisi.</p><?php else:?><p class="mt-2 text-sm"><strong>Tujuan:</strong> <?=e($rencana['tujuan'])?></p><p class="text-sm"><strong>Langkah 1:</strong> <?=e($rencana['langkah_1'])?></p><p class="text-sm"><strong>Langkah 2:</strong> <?=e($rencana['langkah_2'])?></p><?php endif;?></section>
<section class="rounded-2xl border bg-white p-5"><h2 class="font-bold">Jurnal Refleksi</h2><?php if(!$jurnal):?><p class="mt-2 text-sm text-slate-500">Belum ada jurnal.</p><?php else:foreach($jurnal as $j):?><article class="mt-3 border-t pt-3"><p class="text-xs text-slate-500"><?=e(tanggal_id($j['dibuat_pada'],true))?></p><?php foreach(['hal_baru'=>'Hal baru','hambatan'=>'Hambatan','dukungan'=>'Dukungan'] as $k=>$label):if($j[$k]):?><p class="whitespace-pre-wrap text-sm"><strong><?=e($label)?>:</strong> <?=e($j[$k])?></p><?php endif;endforeach;?></article><?php endforeach;endif;?></section></div>
